-- fitness_069_oap_v1_12_0 (M4, data): challenge definition oap@1.12.0 — DATA_MODEL.md 9.1.9, 9.4.1, D117
--
-- D117: the OAP sessions ran far over their time (C 93 min on 4 Nov; A stopped at 59 min half done, B at 65 min).
-- A and B lose about a quarter of their planned time and C a little: fewer accessory sets (A top hold 2 rounds,
-- 90-degree and straight-arm holds 2 sets; B negatives 2 sets, row 3 sets; Pallof press 2 sets everywhere), a small
-- cut in the main work (A assisted one-arm 4 x 3, B weighted pull-ups 5 x 2) and shorter rests on the lighter work
-- (prehab 30 s). prog.A.sth counts the planned rows instead of a fixed six; prog.B.wpu's text says 5 x 2. Like 058 it
-- patches the published previous row (8 jsonb operations, replayed locally to docs/challenges/oap.challenge.v1.json)
-- and proves byte-equality through the guard trigger's server_checksum. No engine change. Manual rollback (only with
-- explicit user approval): delete the definition row before any enrollment references it.

do $$
declare
  base fitness.challenge_definitions;
  d jsonb;
  r fitness.challenge_definitions;
begin
  select * into base from fitness.challenge_definitions where slug = 'oap' and version = '1.11.0' and user_id is null;
  if base.id is null then
    raise exception '069: oap@1.11.0 is missing';
  end if;
  if base.server_checksum <> '333a732cade968c8cc32bc072f9bf284ab36346236fe89454596baab19101f06' then
    raise exception '069: oap@1.11.0 differs from the frozen file (server_checksum %)', base.server_checksum;
  end if;
  if base.definition #>> '{rules,32,id}' <> 'prog.B.wpu' or base.definition #>> '{rules,39,id}' <> 'prog.A.sth' then
    raise exception '069: rules[32] and rules[39] are not prog.B.wpu and prog.A.sth';
  end if;
  d := base.definition;
  d := jsonb_set(d, array['version']::text[], $j$"1.12.0"$j$::jsonb, true);
  d := jsonb_set(d, array['blocks', 'prehab5']::text[], $j$[{"key": "pre_rwc", "exercise": "reverse_wrist_curl_db", "role": "prehab", "sets": 2, "rest_s": 30, "repsRange": [12, 20], "rirTarget": 3, "creditRir": 3, "progression": "delegate:rx", "note": {"en": "Stop with about 3 reps left. The weight goes up once you reach 20."}}, {"key": "pre_ps", "exercise": "db_pronation_supination", "role": "prehab", "sets": 2, "rest_s": 30, "repsRange": [10, 15], "perSide": true, "rirTarget": 3, "creditRir": 3, "progression": "delegate:rx", "note": {"en": "Stop with about 3 reps left. The weight goes up once you reach 15."}}, {"key": "pre_fp", "exercise": "face_pull_cable", "role": "prehab", "sets": 2, "rest_s": 30, "repsRange": [12, 20], "rirTarget": 2, "creditRir": 2, "progression": "delegate:rx", "note": {"en": "Stop with about 2 reps left. The weight goes up once you reach 20."}}]$j$::jsonb, true);
  d := jsonb_set(d, array['templates', 'A1', 'items']::text[], $j$[{"block": "warmup10"}, {"key": "oaa", "exercise": "oap_assisted_machine", "role": "main", "sets": 4, "reps": 3, "perSide": true, "sideOrder": ["L", "R"], "assistPin": "s.reentry ? s.pinA + p.reentryPinOffsetLb : s.pinA", "rirTarget": 1, "creditRir": 1, "rest_s": 120, "calibrationFirstSet": true, "progression": "rule", "note": {"en": "Fresh: this is the challenge movement. The first set is the calibration set: count clean reps and stop with about one left, never to failure (3 clean reps with one left is right). The app adjusts the pin for the remaining sets."}}, {"key": "cal", "exercise": "oa_negative", "role": "main", "sets": 1, "reps": 1, "perSide": true, "sideOrder": ["L", "R"], "ecc_s_target": 5, "assist": "none", "records": "oa_neg5_unassisted", "validForGate": false, "skipIf": "s.elbowTrace || s.reentry", "creditRir": 2, "rest_s": 90, "progression": "rule", "note": {"en": "Calibration negative at the end of exercise 1: one per arm, 5 s down, no help."}}, {"key": "wpu", "exercise": "weighted_pullup", "role": "main", "sets": 4, "reps": 4, "added": "s.reentry ? max(0kg, roundLoad(s.wpuA - p.reentryLoadDropKg, 'belt', 'down')) : s.wpuA", "creditRir": 1, "rest_s": 150, "stopSetOn": ["grip_slip_before_last"], "chalk": true, "progression": "rule", "note": {"en": "If the hand slips before the 4th rep: stop the set, no weight added."}}, {"key": "top", "exercise": "oa_top_hold", "role": "main", "rounds": 2, "attemptsPerRound": 4, "perSide": true, "sideOrder": ["L", "R"], "assist": "none", "creditRir": 2, "rest_s": 90, "progression": "none", "note": {"en": "From a two-arm pull-up release one hand and re-grip before you drop; 4 short attempts per arm per round."}}, {"key": "h90", "exercise": "oa_hold90_machine", "role": "main", "sets": 2, "hold_s": [6, 8], "perSide": true, "sideOrder": ["L", "R"], "assistPin": "s.reentry ? s.pinHold90 + p.reentryPinOffsetLb : s.pinHold90", "creditRir": 2, "rest_s": 90, "progression": "rule", "note": {"en": "Elbow at 90 degrees, 6-8 s still. Fails: +5 lb."}}, {"key": "sth", "exercise": "oa_straight_arm_hold", "role": "main", "sets": 2, "hold_s": "s.sthS", "perSide": true, "sideOrder": ["L", "R"], "creditRir": 2, "rest_s": 90, "replacesHabitToday": "daily_hang", "position": "lastMain", "progression": "rule", "note": {"en": "Fixed neutral handle; deliberately last: the only exercise hanging from one hand at full extension. Replaces today's 17:15 hang."}}, {"key": "pallof", "exercise": "pallof_press", "role": "main", "sets": 2, "reps": 10, "perSide": true, "added": "s.pallofKg", "rirTarget": 2, "creditRir": 2, "rest_s": 45, "progression": "rule", "position": "after:sth", "note": {"en": "Side-on to the cable, handle against your sternum: press straight out and back, the torso does not turn. 2 reps left on every set."}}, {"block": "prehab5"}]$j$::jsonb, true);
  d := jsonb_set(d, array['templates', 'B1', 'items']::text[], $j$[{"block": "warmup10"}, {"key": "wpu", "exercise": "weighted_pullup", "role": "main", "added": "s.reentry ? max(0kg, roundLoad(s.wpuB - p.reentryLoadDropKg, 'belt', 'down')) : s.wpuB", "rirTarget": 2, "creditRir": 2, "rest_s": 150, "stopSetOn": ["grip_slip_before_last"], "progression": "rule", "variantVar": "s.bVariant", "variants": {"6x2": {"sets": 5, "reps": 2}, "ladder123": {"ladders": "p.ladderCount", "rungs": [1, 2, 3], "rest_s_between_rungs": 60, "rest_s_between_ladders": 180, "proposal": "P17"}}, "note": {"en": "The most important sets of the week. All five with 2 reps in reserve: +2.5 kg next week."}}, {"key": "neg", "exercise": "weighted_negative_pullup", "role": "main", "sets": 2, "reps": 2, "added": "s.negB", "ecc_s_target": 5, "creditRir": 2, "rest_s": 180, "skipIf": "s.elbowTrace || s.reentry", "progression": "rule", "note": {"en": "Two arms, 5 s down. Skip at any trace of elbow pain."}}, {"key": "row", "exercise": {"anyOf": ["barbell_row_pronated", "seated_cable_row_wide_pronated", "chest_supported_row_pronated"], "pick": "preference"}, "role": "main", "sets": 3, "reps": 8, "rirTarget": 1, "creditRir": 1, "rest_s": 120, "progression": "delegate:rx", "note": {"en": "Heavy, pronated: counterweight to all the supinated work."}}, {"key": "dip", "exercise": "dip_neutral", "role": "main", "sets": 3, "repsRange": [8, 10], "rirTarget": 2, "creditRir": 2, "rest_s": 90, "progression": "delegate:rx", "bootstrap": "firstSessionBodyweightCalibration", "note": {"en": "Neutral handles, stop every set two reps before failure. First time: log how many clean reps; the load follows from that."}}, {"key": "pallof", "exercise": "pallof_press", "role": "main", "sets": 2, "reps": 10, "perSide": true, "added": "s.pallofKg", "rirTarget": 2, "creditRir": 2, "rest_s": 45, "progression": "rule", "note": {"en": "Side-on to the cable, handle against your sternum: press straight out and back, the torso does not turn. 2 reps left on every set."}}, {"block": "prehab5"}]$j$::jsonb, true);
  d := jsonb_set(d, array['templates', 'C1', 'items']::text[], $j$[{"block": "warmup10"}, {"key": "oaa", "exercise": "oap_assisted_machine", "role": "main", "sets": 3, "reps": 5, "perSide": true, "sideOrder": ["L", "R"], "assistPin": "s.reentry ? s.pinC + p.reentryPinOffsetLb : s.pinC", "rirTarget": 2, "creditRir": 2, "rest_s": 120, "progression": "rule", "note": {"en": "Stop every set two reps before failure. The light version of A's main exercise."}}, {"key": "wpu", "exercise": "weighted_pullup", "role": "main", "sets": 4, "reps": 5, "added": "s.reentry ? max(0kg, roundLoad(s.wpuC - p.reentryLoadDropKg, 'belt', 'down')) : s.wpuC", "creditRir": 1, "rest_s": 150, "stopSetOn": ["grip_slip_before_last"], "chalk": true, "progression": "rule", "note": {"en": "The anchor for all weighted loads."}}, {"key": "scap", "exercise": "oa_scap_pull", "role": "main", "sets": 4, "reps": 3, "perSide": true, "sideOrder": ["L", "R"], "sideRule": "matchLeft", "creditRir": 2, "rest_s": 75, "stopSetOn": ["torso_rotation"], "progression": "none", "note": {"en": "Left first; the right arm does no more clean reps than the left. Stop the set as soon as the torso rotates."}}, {"key": "hang", "exercise": "oa_dead_hang", "role": "main", "sets": 4, "hold_s": "s.oaHangS", "perSide": true, "sideOrder": ["L", "R"], "toFailure": false, "rest_s": 60, "progression": "rule", "note": {"en": "Not to failure; the time counts until the torso starts to rotate."}}, {"key": "pallof", "exercise": "pallof_press", "role": "main", "sets": 2, "reps": 10, "perSide": true, "added": "s.pallofKg", "rirTarget": 2, "creditRir": 2, "rest_s": 45, "progression": "rule", "note": {"en": "Side-on to the cable, handle against your sternum: press straight out and back, the torso does not turn. 2 reps left on every set."}}, {"block": "prehab5"}]$j$::jsonb, true);
  d := jsonb_set(d, array['rules', '32']::text[], $j${"id": "prog.B.wpu", "tag": "A", "stage": "progression", "prio": 50, "on": ["session.completed"], "if": "sess.slot == 'B' && mode == 'normal' && s.bVariant == '6x2' && valid('wpu') && count(ex.wpu.reps) >= ex.wpu.plannedRows && all(ex.wpu.reps >= ex.wpu.targetReps) && min(ex.wpu.rir) >= p.bMinRir", "then": [{"adjust": "s.wpuB", "by": "p.bStepKg", "round": {"profile": "belt", "mode": "nearest"}}], "explain": {"en": "All 5 x 2 with at least 2 reps in reserve: +2.5 kg next week."}, "source": "artifact section 05 / Todoist B"}$j$::jsonb, true);
  d := jsonb_set(d, array['rules', '39']::text[], $j${"id": "prog.A.sth", "tag": "A", "stage": "progression", "prio": 50, "on": ["session.completed"], "if": "sess.slot == 'A' && valid('sth') && s.sthS < p.sthTargetS && count(ex.sth.hold_s) >= ex.sth.plannedRows && all(ex.sth.hold_s >= s.sthS) && !any(ex.sth.torso_rotation)", "then": [{"set": "s.sthS", "to": "p.sthTargetS"}], "explain": {"en": "All four straight-arm holds clean at 6 s: next time 8 s."}, "source": "Todoist A"}$j$::jsonb, true);
  d := jsonb_set(d, array['migrations', '1.11.0']::text[], $j${"varMap": {}, "defaults": {}, "notes": "D117: shorter A and B sessions (about a quarter less) and a lighter C: fewer accessory sets (A top hold 2 rounds, 90-degree and straight-arm holds 2 sets; B negatives 2 sets, row 3 sets; Pallof press 2 sets everywhere), a small cut in the main work (A assisted one-arm 4 sets, B weighted pull-ups 5 x 2) and shorter rests on lighter work; prehab rests 30 s. prog.A.sth counts the planned rows instead of a fixed six. No state var changes."}$j$::jsonb, true);

  insert into fitness.challenge_definitions
    (id, user_id, slug, version, status, schema_version, engine_range, title_en, title_nl, definition,
     jcs_sha256, server_checksum, client_updated_at, device_id, app_version)
  values ('5d1fd20b-9884-5f47-a733-b01e02f2dc2c'::uuid, null, 'oap', '1.12.0', 'published', base.schema_version, base.engine_range,
          base.title_en, base.title_nl, d, 'cd399ef7ccc6b27a5713057c905dabad2a106a96602f8943c9e052f5db9c5e65', repeat('0', 64), now(),
          'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, 'migration')
  on conflict (id) do nothing;

  select * into r from fitness.challenge_definitions where id = '5d1fd20b-9884-5f47-a733-b01e02f2dc2c';
  if r.id is null then
    raise exception '069: oap@1.12.0 was not inserted';
  end if;
  if r.status <> 'published' or r.jcs_sha256 <> 'cd399ef7ccc6b27a5713057c905dabad2a106a96602f8943c9e052f5db9c5e65' then
    raise exception '069: unexpected status % or jcs_sha256 %', r.status, r.jcs_sha256;
  end if;
  if r.server_checksum <> 'cf88f2e161ea03b920dd80adfcc44783eca07ac20948b151be77328804e48d65' then
